import React, { useEffect, useState } from 'react';
import CartItem from '../CartItem/CartItem';
import CartSummary from '../CartSummary/CartSummary';
import './CartMain.css';

const Cart = () => {
    const [cart, setCart] = useState([]);

    // Функція для отримання кошика з localStorage
    const loadCart = () => {
        const savedCart = JSON.parse(localStorage.getItem('cart')) || [];
        setCart(savedCart);
    };

    // Функція для збереження кошика в localStorage
    const saveCart = (newCart) => {
        localStorage.setItem('cart', JSON.stringify(newCart));
        setCart(newCart);
    };

    // Завантажуємо кошик при першому рендерингу
    useEffect(() => {
        loadCart();
    }, []);

    return (
        <div className="cart-page">
            <h1>Ваш кошик</h1>
            <div className="cart-items-list">
                {cart.length > 0 ? (
                    cart.map((item, index) => (
                        <CartItem key={item.id || index} item={item} onCartUpdate={saveCart} />
                    ))
                ) : (
                    <p className="cart-empty-message">Кошик порожній</p>
                )}
            </div>
            <CartSummary cart={cart} />
        </div>
    );
};

export default Cart;
